#!/usr/bin/env python3
# ⏳🤖 Generated by an LLM, pending human review.
"""Bounded loopback devnet smoke; creates disposable funds, never uses a live socket."""
import argparse
from datetime import datetime, timezone, timedelta
import hashlib
import json
import os
from pathlib import Path
import signal
import socket
import subprocess
import time

MAGIC = 1414


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--node", required=True, type=Path)
    p.add_argument("--baseline", required=True, type=Path)
    p.add_argument("--cli", required=True, type=Path)
    p.add_argument("--root", required=True, type=Path, help="New, disposable directory")
    p.add_argument("--config-template", required=True, type=Path)
    p.add_argument("--base-port", type=int, default=34561)
    a = p.parse_args()
    root = a.root.resolve()
    root.mkdir(parents=True, exist_ok=False)
    env = {k: v for k, v in os.environ.items() if not k.startswith("CARDANO_NODE_")}
    processes = {}
    handles = []
    started = time.monotonic()
    deadline = started + 300
    events = root / "receipts.jsonl"

    def emit(stage, **fields):
        row = dict(at=datetime.now(timezone.utc).isoformat(), stage=stage, **fields)
        line = json.dumps(row)
        with events.open("a") as f:
            f.write(line + "\n")
        print(line, flush=True)

    def command(args, check=True):
        args = list(map(str, args))
        result = subprocess.run(args, env=env, text=True, capture_output=True, timeout=30)
        emit("command", argv=args, returncode=result.returncode, stdout=result.stdout, stderr=result.stderr)
        if check:
            result.check_returncode()
        return result

    def cli(*args, check=True):
        return command([a.cli, "dijkstra", *args], check=check)

    def write(path, data):
        path.write_text(json.dumps(data, indent=2) + "\n")

    def wait(label, predicate, seconds=45):
        end = min(deadline, time.monotonic() + seconds)
        while time.monotonic() < end:
            for name, process in processes.items():
                if process.poll() is not None:
                    raise RuntimeError(f"{name} exited {process.returncode}; see its retained log")
            value = predicate()
            if value:
                emit(label, result=value)
                return value
            time.sleep(0.5)
        raise TimeoutError(label)

    def net(name):
        path = root / name / "node.socket"
        assert path.is_relative_to(root) and MAGIC != 164
        return ["--testnet-magic", str(MAGIC), "--socket-path", str(path)]

    def query(name, what, *args):
        r = cli("query", what, *net(name), *args, check=False)
        return json.loads(r.stdout) if r.returncode == 0 else None

    def stop(name):
        process = processes.pop(name, None)
        if process:
            status = Path(f"/proc/{process.pid}/status").read_text()
            emit("resource_sample", node=name,
                 memory=[line for line in status.splitlines() if line.startswith(("VmHWM:", "VmRSS:"))])
            process.send_signal(signal.SIGTERM)
            try:
                process.wait(timeout=20)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=5)
                raise RuntimeError(f"{name} did not shut down cleanly")
            emit("stopped", node=name, returncode=process.returncode)
            assert process.returncode == 0, (name, process.returncode)

    def launch(name, *, suppress=False, forge=False, suffix=""):
        directory = root / name
        binary = a.baseline if name == "baseline" else a.node
        argv = [str(binary), "run", "--config", str(directory / "config.json"),
                "--topology", str(directory / "topology.json"), "--database-path", str(directory / "db"),
                "--socket-path", str(directory / "node.socket"), "--host-addr", "127.0.0.1",
                "--port", str(ports[name])]
        if suppress:
            argv += ["--suppress-inbound-tx-submission"]
        if forge:
            keys = root / "genesis" / "pools-keys" / "pool1"
            argv += ["--shelley-kes-key", str(keys / "kes.skey"),
                     "--shelley-vrf-key", str(keys / "vrf.skey"),
                     "--shelley-operational-certificate", str(keys / "opcert.cert")]
        argv += ["+RTS", "-N2", "-RTS"]
        log = (directory / ("node" + suffix + ".log")).open("w")
        handles.append(log)
        processes[name] = subprocess.Popen(argv, env=env, stdout=log, stderr=subprocess.STDOUT)
        emit("started", node=name, pid=processes[name].pid, argv=argv)
        # A previous clean shutdown can leave the socket pathname present.
        # Require the new process to answer, not merely a filesystem entry.
        wait(name + " socket", lambda: (directory / "node.socket").is_socket() and query(name, "tip"))

    def mempool_has(name, txid):
        value = query(name, "tx-mempool", "tx-exists", txid)
        if isinstance(value, bool):
            return value
        if isinstance(value, dict) and isinstance(value.get("exists"), bool):
            return value["exists"]
        raise RuntimeError(f"unknown mempool query outcome, not absence: {value}")

    def make_tx(name, wallet, label):
        keys = root / "genesis" / "utxo-keys" / ("utxo" + str(wallet))
        addr = cli("address", "build", "--payment-verification-key-file", keys / "utxo.vkey",
                   "--testnet-magic", MAGIC).stdout.strip()
        utxo = query(name, "utxo", "--address", addr)
        assert utxo, (name, addr, utxo)
        txin, item = next(iter(utxo.items()))
        balance = item["value"]["lovelace"]
        body, signed = root / (label + ".body"), root / (label + ".signed")
        cli("transaction", "build-raw", "--tx-in", txin, "--tx-out", addr + "+" + str(balance - 1000000),
            "--fee", 1000000, "--out-file", body)
        cli("transaction", "sign", "--tx-body-file", body, "--signing-key-file", keys / "utxo.skey",
            "--testnet-magic", MAGIC, "--out-file", signed)
        txid = json.loads(cli("transaction", "txid", "--tx-file", signed).stdout)["txhash"]
        assert len(txid) == 64 and all(c in "0123456789abcdef" for c in txid)
        cli("transaction", "submit", *net(name), "--tx-file", signed)
        emit("submitted_devnet_only", node=name, txid=txid, signed_sha256=hashlib.sha256(signed.read_bytes()).hexdigest())
        return txid

    try:
        versions = {name: command([binary, "--version"]).stdout for name, binary in
                    [("candidate", a.node), ("baseline", a.baseline), ("cli", a.cli)]}
        ports = {name: a.base_port + i for i, name in enumerate(["target", "peer", "baseline"])}
        for port in ports.values():
            with socket.socket() as s:
                s.bind(("127.0.0.1", port))
        start = (datetime.now(timezone.utc) + timedelta(seconds=3)).strftime("%Y-%m-%dT%H:%M:%SZ")
        cli("genesis", "create-testnet-data", "--testnet-magic", MAGIC, "--pools", 1,
            "--stake-delegators", 1, "--utxo-keys", 2, "--total-supply", 1000000000000,
            "--start-time", start, "--out-dir", root / "genesis")
        genesis_path = root / "genesis" / "shelley-genesis.json"
        genesis = json.loads(genesis_path.read_text())
        assert genesis["networkMagic"] == MAGIC
        # Keep the ledger forecast horizon longer than the deliberate forging
        # pause; a tiny security parameter would prevent the producer resuming.
        genesis.update(activeSlotsCoeff=0.2, slotLength=0.2, epochLength=5000, securityParam=50,
                       slotsPerKESPeriod=10000, updateQuorum=2)
        genesis["protocolParams"]["protocolVersion"] = dict(major=12, minor=0)
        write(genesis_path, genesis)
        config = json.loads(a.config_template.read_text())
        for key in list(config):
            if key.endswith("GenesisHash") or key.startswith("Test") and "HardForkAt" in key:
                config.pop(key)
        for era in ["Byron", "Shelley", "Alonzo", "Conway", "Dijkstra"]:
            config[era + "GenesisFile"] = str(root / "genesis" / (era.lower() + "-genesis.json"))
        for era in ["Shelley", "Allegra", "Mary", "Alonzo", "Babbage", "Conway", "Dijkstra"]:
            config["Test" + era + "HardForkAtEpoch"] = 0
        config.update(PeerSharing=False, ConsensusMode="PraosMode", ExperimentalProtocolsEnabled=True,
                      ExperimentalHardForksEnabled=True, TraceOptions={
                          "": {"severity": "Info", "detail": "DNormal", "backends": ["Stdout MachineFormat"]},
                          "Mempool": {"severity": "Debug"},
                          "TxSubmission2": {"severity": "Debug"}},
                      TraceOptionTransactions={"fullTxIds": True, "suppressTxBodies": True},
                      TraceOptionTransactionIdentity={"includeMempoolIdentityPairs": True},
                      TraceOptionLeios={"includeTxReferences": True},
                      TxSubmissionInitDelay=0)
        for name in ports:
            directory = root / name
            directory.mkdir()
            write(directory / "config.json", config)
            write(directory / "topology.json", dict(localRoots=[dict(
                accessPoints=[dict(address="127.0.0.1", port=port) for peer, port in ports.items() if peer != name],
                advertise=False, valency=2, trustable=True)], publicRoots=[], useLedgerAfterSlot=-1,
                bootstrapPeers=None))
        emit("identity", magic=MAGIC, system_start=start, versions=versions,
             genesis_sha256=hashlib.sha256(genesis_path.read_bytes()).hexdigest())
        launch("peer", forge=True)
        launch("target", suppress=True)
        launch("baseline")
        wait("all sync at least three blocks", lambda: all((query(n, "tip") or {}).get("block", 0) >= 3 for n in ports), 60)
        # Freeze block production while testing mempool direction, preventing
        # block inclusion from masquerading as peer transaction admission.
        stop("peer")
        launch("peer", suffix="-relay")
        def tips_equal():
            tips = [query(n, "tip") for n in ports]
            return all(tips) and len({t["hash"] for t in tips}) == 1
        wait("tips equal before admission", tips_equal)
        peer_tx = make_tx("peer", 1, "peer-tx")
        wait("peer tx control received by baseline", lambda: mempool_has("baseline", peer_tx))
        observations = []
        for _ in range(10):
            present = mempool_has("target", peer_tx)
            observations.append(present)
            assert not present, "flag ON admitted peer transaction"
            time.sleep(0.5)
        local_tx = make_tx("target", 2, "local-tx")
        wait("local accepted and diffused outward", lambda: all(mempool_has(n, local_tx) for n in ports))
        emit("ON", peer_tx=peer_tx, local_tx=local_tx, peer_absence_observations=observations)
        stop("target")
        launch("target", suffix="-off")
        wait("OFF stock peer admission", lambda: mempool_has("target", peer_tx))
        emit("OFF", peer_tx=peer_tx, admitted=True)
        stop("peer")
        launch("peer", forge=True, suffix="-forge")
        wait("locally submitted transaction included and block fetched", lambda:
             bool(query("target", "utxo", "--tx-in", local_tx + "#0")), 60)
        # Exact payload parity for the same serialized transaction, with distinct
        # timestamps/envelopes intentionally excluded from the comparison.
        stop("baseline")
        stop("target")
        def identities(path, txid):
            matches = []
            for line in path.read_text().splitlines():
                try:
                    value = json.loads(line)
                except ValueError:
                    continue
                def visit(v):
                    if isinstance(v, dict):
                        identity = v.get("txIdentity")
                        if isinstance(identity, dict) and identity.get("ledgerTxId") == txid:
                            matches.append(identity)
                        for child in v.values():
                            visit(child)
                    elif isinstance(v, list):
                        for child in v:
                            visit(child)
                visit(value)
            return matches
        candidate = identities(root / "target/node.log", local_tx)
        baseline = identities(root / "baseline/node.log", local_tx)
        assert candidate and baseline, "missing identity output"
        assert all(v == candidate[0] for v in candidate + baseline), "schema parity failure"
        assert candidate[0]["schema"] == 2 and candidate[0]["encoding"] == "leios-block-transaction"
        emit("schema2_parity", identity=candidate[0], candidate_records=len(candidate), baseline_records=len(baseline))
        emit("PASS", elapsed_seconds=time.monotonic() - started)
    finally:
        failures = []
        for name in list(processes):
            try:
                stop(name)
            except Exception as exc:
                failures.append(str(exc))
        for handle in handles:
            handle.close()
        if failures:
            raise RuntimeError("cleanup failures: " + "; ".join(failures))


if __name__ == "__main__":
    main()
